#!/usr/bin/env node
/**
 * generate-project.js
 *
 * Writes the complete SteamGauge project (72 files: app/, components/,
 * lib/, supabase/, docs/ and root configuration) into a folder.
 *
 *   node generate-project.js                 write into the current folder
 *   node generate-project.js ./steamgauge     write into another folder
 *   node generate-project.js --dry-run       show what would happen, write nothing
 *   node generate-project.js --list          list the bundled files and exit
 *   node generate-project.js --force-config  also replace existing config files
 *
 * It is safe to run inside an existing project:
 *
 *   - A file that does not exist yet is created.
 *   - A file that already matches is left alone.
 *   - A CODE file that differs is replaced, after the old version is copied to
 *     .steamgauge-backup/<timestamp>/<same path>.
 *   - A CONFIG file that differs (package.json, tsconfig.json, next.config.ts,
 *     postcss.config.mjs, vercel.json, .gitignore, .env.example,
 *     app/globals.css, app/layout.tsx) is KEPT as it is, unless you pass
 *     --force-config. Your own setup wins by default.
 *   - .env and .env.local are never read or written.
 *
 * Needs Node.js 18 or later. No dependencies. Generated 2026-11-17.
 */
